const text = $json.output[0].content[0].text;
const limit = 3950;

const chatId = $('Telegram Trigger2').item.json.message.chat.id;

const chunks = [];
let current = '';

const paragraphs = text.split(/\n+/);

for (const paragraph of paragraphs) {
  const part = paragraph.trim();

  if (!part) continue;

  if ((current + '\n\n' + part).length <= limit) {
    current = current ? current + '\n\n' + part : part;
  } else {
    if (current) {
      chunks.push({
        json: {
          chat_id: chatId,
          text: current,
        },
      });
    }

    if (part.length <= limit) {
      current = part;
    } else {
      for (let i = 0; i < part.length; i += limit) {
        chunks.push({
          json: {
            chat_id: chatId,
            text: part.slice(i, i + limit),
          },
        });
      }

      current = '';
    }
  }
}

if (current) {
  chunks.push({
    json: {
      chat_id: chatId,
      text: current,
    },
  });
}

return chunks;
